<script setup lang="ts">
import { Close } from './internal/icons';
import RenderNode from './internal/RenderNode';
import { computed, ref, watch, nextTick, onBeforeUnmount, getCurrentInstance } from 'vue'; import type { Ref } from 'vue';
import Button from './Button.vue'; import { useDialog } from './internal/dialog'; import { positionForRects, type FloatingPosition, type PopupPlacement } from './internal/geometry';
import './styles/theme.css'; import './styles/tour.css';
type Target = HTMLElement | null | undefined | (() => HTMLElement | null | undefined) | Ref<HTMLElement | null>;
interface Step { title: import('vue').VNodeChild; description?: import('vue').VNodeChild; cover?: import('vue').VNodeChild; target?: Target; placement?: PopupPlacement; mask?: boolean; nextButtonProps?: { children?: string; onClick?: () => void }; prevButtonProps?: { children?: string; onClick?: () => void } }
const props = withDefaults(defineProps<{ steps: Step[]; open?: boolean; current?: number; defaultCurrent?: number; mask?: boolean; type?: 'default' | 'primary'; arrow?: boolean; gap?: number; radius?: number; closable?: boolean; zIndex?: number; scrollIntoViewOptions?: boolean | ScrollIntoViewOptions }>(), { defaultCurrent: 0, mask: true, type: 'default', arrow: true, gap: 6, radius: 10, closable: true, zIndex: 1200, scrollIntoViewOptions: () => ({ block: 'center', behavior: 'smooth' }) });
const emit = defineEmits<{ 'update:open': [value: boolean]; close: [current: number]; finish: []; 'update:current': [value: number]; change: [current: number] }>(); const inner = ref(props.defaultCurrent); const index = computed(() => Math.min(Math.max(props.current ?? inner.value, 0), Math.max(0, props.steps.length - 1))); const step = computed(() => props.steps[index.value]); const card = ref<HTMLElement | null>(null), spot = ref<{ top: number; left: number; width: number; height: number } | null>(null), position = ref<FloatingPosition | null>(null); const id = `at-tour-${getCurrentInstance()?.uid}`;
function close() { emit('update:open', false); emit('close', index.value); }
function change(value: number) { if (props.current === undefined) inner.value = value; emit('update:current', value); emit('change', value); }
function next() { step.value?.nextButtonProps?.onClick?.(); if (index.value >= props.steps.length - 1) { emit('finish'); close(); } else change(index.value + 1); }
function previous() { step.value?.prevButtonProps?.onClick?.(); change(Math.max(0, index.value - 1)); }
useDialog(() => !!props.open && !!step.value, card, close, () => true);
function target() { const value = step.value?.target; return typeof value === 'function' ? value() : value && 'value' in value ? value.value : value; }
function update() { const element = target(); if (!element) { spot.value = null; position.value = null; return; } const rect = element.getBoundingClientRect(); const padded = { top: rect.top - props.gap, left: rect.left - props.gap, width: rect.width + props.gap * 2, height: rect.height + props.gap * 2, right: rect.right + props.gap, bottom: rect.bottom + props.gap }; spot.value = padded; if (card.value) position.value = positionForRects(padded, card.value.getBoundingClientRect(), step.value?.placement ?? 'bottom', props.arrow ? 14 : 8); }
let cleanup: (() => void) | undefined;
watch([() => props.open, index], async ([open], _, invalidate) => { cleanup?.(); cleanup = undefined; if (!open || typeof window === 'undefined') return; let cancelled = false; invalidate(() => { cancelled = true; }); await nextTick(); if (cancelled) return; const element = target(); if (element && props.scrollIntoViewOptions) element.scrollIntoView(typeof props.scrollIntoViewOptions === 'object' ? { ...props.scrollIntoViewOptions, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : props.scrollIntoViewOptions.behavior } : undefined); update(); card.value?.focus(); const frame = requestAnimationFrame(update); const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(update); if (card.value) observer?.observe(card.value); if (element) observer?.observe(element); window.addEventListener('resize', update); window.addEventListener('scroll', update, true); cleanup = () => { cancelAnimationFrame(frame); observer?.disconnect(); window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); }; }, { immediate: true, flush: 'post' });
watch(() => props.open, open => { if (open && props.current === undefined) inner.value = props.defaultCurrent; }); onBeforeUnmount(() => cleanup?.());
</script>
<template><Teleport to="body"><div v-if="open && step" :class="['at-tour', `at-tour--${type}`]" :style="{ zIndex }"><svg v-if="step.mask ?? mask" class="at-tour__mask" aria-hidden="true"><defs><mask :id="`${id}-mask`"><rect x="0" y="0" width="100%" height="100%" fill="#fff" /><rect v-if="spot" :x="spot.left" :y="spot.top" :width="spot.width" :height="spot.height" :rx="radius" fill="#000" class="at-tour__hole" /></mask></defs><rect x="0" y="0" width="100%" height="100%" fill="rgb(20 22 45 / 55%)" :mask="`url(#${id}-mask)`" /></svg><div v-if="spot" class="at-tour__spotlight" :style="{ top: `${spot.top}px`, left: `${spot.left}px`, width: `${spot.width}px`, height: `${spot.height}px`, borderRadius: `${radius}px` }" aria-hidden="true" /><div ref="card" role="dialog" aria-modal="true" :aria-labelledby="`${id}-title`" :aria-describedby="step.description ? `${id}-description` : undefined" tabindex="-1" :class="['at-tour__card', { 'at-tour__card--arrow': spot && arrow, 'at-tour__card--centered': !spot }]" :data-placement="position?.placement ?? step.placement ?? 'bottom'" :style="spot ? { top: `${position?.top ?? -9999}px`, left: `${position?.left ?? -9999}px` } : { top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }" @keydown.right.prevent="index < steps.length - 1 && next()" @keydown.left.prevent="index > 0 && previous()"><button v-if="closable" type="button" class="at-tour__close" aria-label="关闭引导" @click="close"><Close :size="14" /></button><div v-if="step.cover || $slots.cover" class="at-tour__cover"><slot name="cover" :step="step"><RenderNode :content="step.cover" /></slot></div><div class="at-tour__body"><h3 :id="`${id}-title`" class="at-tour__title"><RenderNode :content="step.title" /></h3><p v-if="step.description" :id="`${id}-description`" class="at-tour__description"><RenderNode :content="step.description" /></p></div><footer class="at-tour__footer"><div class="at-tour__indicators" :aria-label="`第 ${index + 1} 步，共 ${steps.length} 步`"><slot name="indicators" :current="index" :total="steps.length"><span v-for="(_, dot) in steps" :key="dot" :class="['at-tour__dot', { 'at-tour__dot--active': dot === index }]" /></slot></div><div class="at-tour__actions"><Button v-if="index > 0" size="sm" :variant="type === 'primary' ? 'ghost' : 'secondary'" class="at-tour__button" @click="previous">{{ step.prevButtonProps?.children ?? '上一步' }}</Button><Button size="sm" variant="primary" class="at-tour__button at-tour__button--next" @click="next">{{ step.nextButtonProps?.children ?? (index === steps.length - 1 ? '完成' : '下一步') }}</Button></div></footer></div></div></Teleport></template>
